import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Auth.css";

export default function Auth() {
  const [tab, setTab] = useState("login"); // "login" | "register"
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    name: "", email: "", password: "", college: "", stream: "", year: ""
  });
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const streams = ["Computer Science", "Electronics", "Mechanical", "Civil", "Commerce", "Arts", "Science", "Law", "Medicine", "Other"];
  const years = ["1st Year", "2nd Year", "3rd Year", "4th Year", "Graduate", "Post Graduate"];

  function validate() {
    const errs = {};
    if (!form.email) errs.email = "Email is required";
    else if (!/\S+@\S+\.\S+/.test(form.email)) errs.email = "Invalid email address";
    if (!form.password) errs.password = "Password is required";
    else if (form.password.length < 6) errs.password = "Minimum 6 characters";
    if (tab === "register") {
      if (!form.name) errs.name = "Full name is required";
      if (!form.college) errs.college = "College name is required";
    }
    return errs;
  }

  function handleChange(e) {
    setForm(f => ({ ...f, [e.target.name]: e.target.value }));
    setErrors(err => ({ ...err, [e.target.name]: "" }));
  }

  function handleSubmit() {
    const errs = validate();
    if (Object.keys(errs).length > 0) { setErrors(errs); return; }
    setLoading(true);
    // Simulate API call — replace with real POST request in backend phase
    setTimeout(() => {
      setLoading(false);
      navigate("/dashboard");
    }, 1500);
  }

  return (
    <div className="auth-page">
      {/* Background */}
      <div className="auth-bg">
        <div className="auth-orb auth-orb-1" />
        <div className="auth-orb auth-orb-2" />
        <div className="auth-grid" />
      </div>

      {/* Logo */}
      <Link to="/" className="auth-logo">
        <span className="auth-logo-icon">◈</span>
        Skill<em>Path</em>
      </Link>

      <div className="auth-container">
        {/* LEFT PANEL */}
        <div className="auth-left">
          <div className="auth-left-content">
            <div className="auth-left-badge">⚡ SPARK Assessment</div>
            <h2>Your career clarity starts here.</h2>
            <p>Join 50,000+ students who discovered their perfect career path using SkillPath's science-backed assessment.</p>

            <div className="auth-features">
              {[
                { icon: "🎯", text: "5-Dimensional SPARK Assessment" },
                { icon: "📊", text: "Skill Gap Tracker for your target career" },
                { icon: "🏆", text: "Gamified XP & achievement badges" },
                { icon: "🤝", text: "1-on-1 expert mentor sessions" },
              ].map(f => (
                <div key={f.text} className="auth-feature-item">
                  <span className="af-icon">{f.icon}</span>
                  <span>{f.text}</span>
                </div>
              ))}
            </div>

            <div className="auth-testimonial">
              <div className="at-quote">"</div>
              <p>SkillPath helped me realise I was meant for UX design. The assessment was surprisingly accurate!</p>
              <div className="at-author">
                <div className="at-avatar">A</div>
                <div>
                  <strong>Ananya Sharma</strong>
                  <span>IIT Bombay · UX Designer</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* RIGHT PANEL - FORM */}
        <div className="auth-right">
          <div className="auth-card">
            {/* TABS */}
            <div className="auth-tabs">
              <button
                className={`auth-tab ${tab === "login" ? "auth-tab--active" : ""}`}
                onClick={() => { setTab("login"); setErrors({}); }}
              >
                Log In
              </button>
              <button
                className={`auth-tab ${tab === "register" ? "auth-tab--active" : ""}`}
                onClick={() => { setTab("register"); setErrors({}); }}
              >
                Create Account
              </button>
              <div className="auth-tab-slider" style={{ transform: `translateX(${tab === "login" ? "0%" : "100%"})` }} />
            </div>

            <div className="auth-form">
              {/* REGISTER ONLY FIELDS */}
              {tab === "register" && (
                <>
                  <div className="form-group">
                    <label>Full Name</label>
                    <input
                      type="text"
                      name="name"
                      placeholder="Arjun Krishnan"
                      value={form.name}
                      onChange={handleChange}
                      className={errors.name ? "input-error" : ""}
                    />
                    {errors.name && <span className="form-error">{errors.name}</span>}
                  </div>
                </>
              )}

              {/* EMAIL */}
              <div className="form-group">
                <label>Email Address</label>
                <input
                  type="email"
                  name="email"
                  placeholder="you@college.edu"
                  value={form.email}
                  onChange={handleChange}
                  className={errors.email ? "input-error" : ""}
                />
                {errors.email && <span className="form-error">{errors.email}</span>}
              </div>

              {/* PASSWORD */}
              <div className="form-group">
                <label>Password</label>
                <div className="input-password-wrap">
                  <input
                    type={showPass ? "text" : "password"}
                    name="password"
                    placeholder={tab === "register" ? "Min. 6 characters" : "Enter your password"}
                    value={form.password}
                    onChange={handleChange}
                    className={errors.password ? "input-error" : ""}
                  />
                  <button className="pass-toggle" onClick={() => setShowPass(s => !s)} type="button">
                    {showPass ? "🙈" : "👁️"}
                  </button>
                </div>
                {errors.password && <span className="form-error">{errors.password}</span>}
              </div>

              {/* REGISTER ONLY — COLLEGE + STREAM + YEAR */}
              {tab === "register" && (
                <>
                  <div className="form-group">
                    <label>College / University</label>
                    <input
                      type="text"
                      name="college"
                      placeholder="PSG College of Technology"
                      value={form.college}
                      onChange={handleChange}
                      className={errors.college ? "input-error" : ""}
                    />
                    {errors.college && <span className="form-error">{errors.college}</span>}
                  </div>

                  <div className="form-row">
                    <div className="form-group">
                      <label>Stream / Branch</label>
                      <select name="stream" value={form.stream} onChange={handleChange}>
                        <option value="">Select stream</option>
                        {streams.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div className="form-group">
                      <label>Year of Study</label>
                      <select name="year" value={form.year} onChange={handleChange}>
                        <option value="">Select year</option>
                        {years.map(y => <option key={y} value={y}>{y}</option>)}
                      </select>
                    </div>
                  </div>
                </>
              )}

              {/* FORGOT PASSWORD */}
              {tab === "login" && (
                <div className="form-forgot">
                  <a href="#">Forgot password?</a>
                </div>
              )}

              {/* SUBMIT */}
              <button
                className={`auth-submit ${loading ? "auth-submit--loading" : ""}`}
                onClick={handleSubmit}
                disabled={loading}
              >
                {loading ? (
                  <span className="auth-spinner" />
                ) : tab === "login" ? (
                  "Log In to SkillPath →"
                ) : (
                  "Create My Account →"
                )}
              </button>

              {/* DIVIDER */}
              <div className="auth-divider"><span>or continue with</span></div>

              {/* SOCIAL LOGIN */}
              <div className="auth-social">
                <button className="social-btn">
                  <svg width="18" height="18" viewBox="0 0 24 24"><path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/><path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/></svg>
                  Google
                </button>
                <button className="social-btn">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="#0A66C2"><path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 01-2.063-2.065 2.064 2.064 0 112.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/></svg>
                  LinkedIn
                </button>
              </div>

              {/* SWITCH TAB */}
              <p className="auth-switch">
                {tab === "login" ? (
                  <>Don't have an account? <button onClick={() => setTab("register")}>Sign up free</button></>
                ) : (
                  <>Already have an account? <button onClick={() => setTab("login")}>Log in</button></>
                )}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
